import { createSdkError } from './errors.js';
import { createHttpClient } from './http.js';
import { createSessionController, normalizeTokenResponse } from './session.js';
import { createStateStore } from './state.js';
import { authenticateDevice, deriveDevicePrivateKey, deriveLegacyDevicePrivateKey, } from './device-auth.js';
export function createDeviceSdk(options) {
    let persisted = null;
    const state = createStateStore({
        clear() {
            persisted = null;
        },
        read() {
            return persisted;
        },
        write(next) {
            persisted = next;
        },
    });
    let disposed = false;
    let disposePromise = null;
    const guardedState = {
        getState() {
            return state.getState();
        },
        onChange(listener) {
            return state.onChange(listener);
        },
        applyPersistedState(next) {
            if (disposed) {
                return;
            }
            state.applyPersistedState(next);
        },
        setAuthenticated(next) {
            if (disposed) {
                return;
            }
            state.setAuthenticated(next);
        },
        setRecovering(next) {
            if (disposed) {
                return;
            }
            state.setRecovering(next);
        },
        setAuthenticatedLocal(next) {
            if (disposed) {
                return;
            }
            state.setAuthenticatedLocal(next);
        },
        setAnonymous() {
            if (disposed) {
                return;
            }
            state.setAnonymous();
        },
        setAnonymousLocal() {
            if (disposed) {
                return;
            }
            state.setAnonymousLocal();
        },
    };
    const fetch = options.fetch ?? globalThis.fetch?.bind(globalThis);
    if (!fetch) {
        throw createSdkError('sdk_init_failed', 'fetch is unavailable');
    }
    const http = createHttpClient({
        baseUrl: options.serverBaseUrl,
        fetch,
    });
    const privateKey = options.privateKey
        ? deriveDevicePrivateKey(options.privateKey)
        : deriveLegacyDevicePrivateKey(options.privateKeySeed ?? '');
    const now = options.now ?? (() => Date.now());
    const session = createSessionController({
        http,
        now,
        state: guardedState,
    });
    const ready = (async () => {
        await authenticateDevice({
            http,
            privateKey,
            session: {
                async acceptSessionResponse(response) {
                    const acceptedSession = normalizeTokenResponse(response, now);
                    if (disposed) {
                        await bestEffortLogout(acceptedSession.accessToken);
                        return;
                    }
                    try {
                        await session.acceptSessionResponse(response);
                    }
                    finally {
                        if (disposed) {
                            await bestEffortLogout(acceptedSession.accessToken);
                        }
                    }
                },
            },
        });
    })();
    return {
        ready,
        dispose,
        [Symbol.asyncDispose]() {
            return dispose();
        },
        session: {
            getState() {
                return state.getState();
            },
            onChange(listener) {
                return state.onChange(listener);
            },
            async refresh() {
                assertNotDisposed();
                return await session.refresh();
            },
            async logout() {
                assertNotDisposed();
                return await session.logout();
            },
        },
    };
    function assertNotDisposed() {
        if (!disposed) {
            return;
        }
        throw createSdkError('disposed_session', 'Device SDK instance has been disposed');
    }
    function dispose() {
        if (disposePromise) {
            return disposePromise;
        }
        disposed = true;
        disposePromise = (async () => {
            try {
                await session.logout();
            }
            catch {
                // Deterministic local disposal hides remote failures.
            }
            finally {
                persisted = null;
                state.setAnonymous();
            }
        })();
        return disposePromise;
    }
    async function bestEffortLogout(accessToken) {
        if (!accessToken) {
            return;
        }
        try {
            await http.postJson('/session/logout', undefined, {
                accessToken,
            });
        }
        catch {
            // Disposal should still clear local state when remote logout fails.
        }
    }
}
